//! Test fixtures: instance identity documents signed by a throwaway test certificate in place of AWS's. They were made once with
//! `openssl smime -sign` (and `openssl cms -sign -stream` for the BER form); the private key was discarded, so nothing here can
//! sign. The real AWS certificate path is tested separately against the pinned table; **no real AWS-signed sample exists in AWS's
//! public documentation**, so a real signed document is verified only by the owner's run on an existing instance.
//!
//! The documents (all account 123456789012 unless named): `OK` is us-east-1, instance i-0123456789abcdef0, launched
//! 2027-01-15T07:00:00Z. The others differ in exactly one thing.

pub const TEST_CERT: &str = "";
pub const OK: &str = "";
pub const NOATTR: &str = "";
pub const STREAM: &str = "";
pub const OTHER_ACCOUNT: &str = "";
pub const OTHER_REGION: &str = "";
pub const UNKNOWN_REGION: &str = "";
pub const OTHER_INSTANCE: &str = "";
pub const STALE: &str = "";
